    private static final Map<String,String> NORMALIZED_HEADERS=normalizedHeaders();

    private static Map<String,String> normalizedHeaders(){Map<String,String> result=new HashMap<>();HEADERS.forEach((key,value)->result.put(normalizeHeader(key),value));return Map.copyOf(result);}
    private static String normalizeHeader(String value){return value==null?"":value.toLowerCase(Locale.ROOT).replaceAll("[\\s_\\-（）()【】\\[\\]：:./\\\\]+","").trim();}
    private static String canonicalHeader(String value){return NORMALIZED_HEADERS.getOrDefault(normalizeHeader(value),value==null?"":value.trim());}

