    @PostMapping(value="/imports/preview",consumes="multipart/form-data")
    public ApiResponse<Map<String,Object>> preview(@RequestParam String type,@RequestPart("file") MultipartFile file,@AuthenticationPrincipal AuthUser user,HttpServletRequest request){
        manageImport(user);String docType=docType(type);if(file==null||file.isEmpty()||!Objects.requireNonNullElse(file.getOriginalFilename(),"").toLowerCase(Locale.ROOT).endsWith(".xlsx"))throw new IllegalArgumentException("请选择 .xlsx 文件");
        try{
            byte[] bytes=file.getBytes();String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
            var existing=db.query("SELECT id,batch_no batchNo,status,total_rows totalRows,created_rows createdRows,updated_rows updatedRows,duplicate_rows duplicateRows,unmatched_rows unmatchedRows,error_rows errorRows FROM fulfillment_import_batches WHERE document_type=? AND file_sha256=? ORDER BY id DESC LIMIT 1",rs->rs.next()?row(rs):null,docType,sha);
            if(existing!=null){existing.put("alreadyImported",true);return ApiResponse.ok(existing);}
            List<Map<String,Object>> parsed=parse(file,docType);LocalDate today=LocalDate.now(ZONE);String batchNo="FUL"+today.format(DateTimeFormatter.BASIC_ISO_DATE)+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase(Locale.ROOT);
            Path dir=Path.of(importDir,today.toString()).toAbsolutePath().normalize();Files.createDirectories(dir);String original=Path.of(Objects.requireNonNullElse(file.getOriginalFilename(),"platform.xlsx")).getFileName().toString();Path stored=dir.resolve(batchNo+"_"+original).normalize();if(!stored.startsWith(dir))throw new IllegalArgumentException("文件名无效");Files.write(stored,bytes,StandardOpenOption.CREATE_NEW);
            db.update("INSERT INTO fulfillment_import_batches(batch_no,document_type,original_filename,stored_file_path,file_sha256,status,total_rows,created_by) VALUES (?,?,?, ?,?,'PREVIEWED',?,?)",batchNo,docType,original,stored.toString(),sha,parsed.size(),user.id());long batch=lastId();
            int unmatched=0,errors=0;
            for(Map<String,Object> item:parsed){List<String> problems=new ArrayList<>();validate(item,docType,problems);Long shopId=null;
                if(!problems.contains("店铺/账号标识不存在或未启用"))shopId=db.query("SELECT id FROM shops WHERE shop_identifier=? AND status='ACTIVE' AND is_deleted=FALSE",rs->rs.next()?rs.getLong(1):null,str(item,"shop_identifier"));
                if(shopId==null&&item.get("shop_identifier")!=null&&!str(item,"shop_identifier").isBlank())problems.add("店铺/账号标识不存在或未启用");
                Long skuId=null;if(shopId!=null){skuId=db.query("SELECT sku_id FROM shop_sku_mappings WHERE shop_id=? AND platform_sku=? AND status='ACTIVE' AND is_deleted=FALSE",rs->rs.next()?rs.getLong(1):null,shopId,str(item,"platform_sku"));}
                String status=!problems.isEmpty()?"ERROR":skuId==null?"UNMATCHED":"READY";if(status.equals("ERROR"))errors++;if(status.equals("UNMATCHED"))unmatched++;
                Long batchShop=shopId;Long batchSku=skuId;
                db.update("INSERT INTO fulfillment_import_rows(batch_id,source_row_number,raw_data,normalized_data,validation_errors,row_status) VALUES (?,?,CAST(? AS JSON),CAST(? AS JSON),CAST(? AS JSON),?)",batch,item.get("_row"),jsonText(item.get("_raw")),jsonText(item),jsonText(problems),status);
            }
            db.update("UPDATE fulfillment_import_batches SET unmatched_rows=?,error_rows=? WHERE id=?",unmatched,errors,batch);
            audit(user,request,"fulfillment.import.preview","fulfillment_import_batch",batchNo,Map.of("type",docType,"rows",parsed.size(),"errors",errors,"unmatched",unmatched));
            return ApiResponse.ok(batchSummary(batch));
        }catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("平台文件预览失败："+e.getMessage());}
    }

    @GetMapping("/imports/{id}")
    public ApiResponse<Map<String,Object>> importDetail(@PathVariable long id,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="100")int pageSize,@AuthenticationPrincipal AuthUser user){view(user);Map<String,Object> result=batchSummary(id);int p=Math.max(1,page),s=Math.min(500,Math.max(1,pageSize));result.put("rows",db.queryForList("SELECT id,source_row_number rowNumber,raw_data rawData,normalized_data normalizedData,validation_errors validationErrors,row_status rowStatus FROM fulfillment_import_rows WHERE batch_id=? ORDER BY source_row_number LIMIT ? OFFSET ?",id,s,(p-1)*s));return ApiResponse.ok(result);}

    @PostMapping("/imports/{id}/commit") @Transactional
    public ApiResponse<Map<String,Object>> commit(@PathVariable long id,@AuthenticationPrincipal AuthUser user,HttpServletRequest request){
        manageImport(user);Map<String,Object> batch=lockBatch(id);if(!"PREVIEWED".equals(batch.get("status")))throw new IllegalArgumentException("该导入批次已经处理");
        List<Map<String,Object>> rows=db.queryForList("SELECT id,row_status rowStatus,normalized_data normalizedData FROM fulfillment_import_rows WHERE batch_id=? AND row_status IN ('READY','UNMATCHED') ORDER BY source_row_number",id);
        int created=0,updated=0,duplicates=0,unmatched=0;
        for(Map<String,Object> source:rows){Map<String,Object> v=readObject(source.get("normalizedData"));String status=String.valueOf(source.get("rowStatus"));Long shopId=db.query("SELECT id FROM shops WHERE shop_identifier=? AND status='ACTIVE' AND is_deleted=FALSE",rs->rs.next()?rs.getLong(1):null,str(v,"shop_identifier"));Long skuId=shopId==null?null:db.query("SELECT sku_id FROM shop_sku_mappings WHERE shop_id=? AND platform_sku=? AND status='ACTIVE' AND is_deleted=FALSE",rs->rs.next()?rs.getLong(1):null,shopId,str(v,"platform_sku"));status=skuId==null?"UNMATCHED":"READY";if(skuId==null)unmatched++;
            String type=str(v,"document_type"),platform=blankDefault(str(v,"platform"),"ALIEXPRESS"),account=str(v,"shop_identifier"),sourceId=str(v,"source_document_id");Long documentId=db.query("SELECT id FROM fulfillment_documents WHERE document_type=? AND platform=? AND shop_identifier=? AND source_document_id=? FOR UPDATE",rs->rs.next()?rs.getLong(1):null,type,platform,account,sourceId);
            boolean isNew=documentId==null;
            if(isNew){String docNo=nextNo("FD");db.update("INSERT INTO fulfillment_documents(document_no,document_type,platform,shop_id,shop_identifier,source_document_id,source_status,group_batch_id,target_platform_warehouse,warehouse_id,local_status,platform_updated_at,appointment_no,pickup_start,pickup_end,platform_snapshot,created_from_batch_id) VALUES (?,?,?,?,?,?,?,?,?,1,?,?,?,?,?,CAST(? AS JSON),?)",docNo,type,platform,shopId,account,sourceId,str(v,"source_status"),str(v,"group_batch_id"),str(v,"target_platform_warehouse"),skuId==null?"SKU_UNMATCHED":"READY_TO_PICK",dateTime(v.get("updated_at")),str(v,"appointment_no"),dateTime(v.get("pickup_start")),dateTime(v.get("pickup_end")),jsonText(documentSnapshot(v)),id);documentId=lastId();}
            else{String oldSnapshot=db.queryForObject("SELECT CAST(platform_snapshot AS CHAR) FROM fulfillment_documents WHERE id=?",String.class,documentId);String docSnapshot=jsonText(documentSnapshot(v));boolean platformChanged=oldSnapshot!=null&&!oldSnapshot.equals(docSnapshot);Integer localWork=db.queryForObject("SELECT COUNT(*) FROM fulfillment_dispatches WHERE document_id=?",Integer.class,documentId);db.update("UPDATE fulfillment_documents SET shop_id=COALESCE(?,shop_id),source_status=?,group_batch_id=?,target_platform_warehouse=COALESCE(?,target_platform_warehouse),platform_updated_at=COALESCE(?,platform_updated_at),appointment_no=COALESCE(?,appointment_no),pickup_start=COALESCE(?,pickup_start),pickup_end=COALESCE(?,pickup_end),platform_snapshot=CAST(? AS JSON),local_status=CASE WHEN local_status='SKU_UNMATCHED' AND ? IS NOT NULL THEN 'READY_TO_PICK' ELSE local_status END WHERE id=?",shopId,str(v,"source_status"),str(v,"group_batch_id"),str(v,"target_platform_warehouse"),dateTime(v.get("updated_at")),str(v,"appointment_no"),dateTime(v.get("pickup_start")),dateTime(v.get("pickup_end")),docSnapshot,skuId,documentId);if(platformChanged&&localWork!=null&&localWork>0)createPlatformChangedException(documentId,str(v,"source_document_id"),oldSnapshot,docSnapshot);}
            String lineKey=stableLineKey(v);Long itemId=db.query("SELECT id FROM fulfillment_document_items WHERE document_id=? AND source_line_key=? FOR UPDATE",rs->rs.next()?rs.getLong(1):null,documentId,lineKey);String rowResult;
            BigDecimal qty=decimal(v.get("quantity"));if(itemId==null){db.update("INSERT INTO fulfillment_document_items(document_id,source_line_id,source_line_key,platform_sku_id,platform_sku,sku_id,order_mode,order_date,ordered_qty,imported_state,platform_updated_at,raw_snapshot) VALUES (?,?,?,?,?,?,?,?,?,?,?,CAST(? AS JSON))",documentId,str(v,"source_line_id"),lineKey,str(v,"platform_sku_id"),str(v,"platform_sku"),skuId,"JIT_ORDER".equals(type)?"JIT":"WAREHOUSE",date(v.get("order_date")),qty,str(v,"source_status"),dateTime(v.get("updated_at")),jsonText(v));itemId=lastId();rowResult="CREATED";created++;if(skuId==null)createUnmatchedException(shopId,str(v,"platform_sku"),itemId,sourceId);}
            else{BigDecimal shipped=decimalOrZero(db.queryForObject("SELECT COALESCE(SUM(di.shipped_qty),0) FROM fulfillment_dispatch_items di JOIN fulfillment_dispatches d ON d.id=di.dispatch_id WHERE di.document_item_id=? AND d.status='HANDED_OFF'",BigDecimal.class,itemId));String previous=db.queryForObject("SELECT CAST(raw_snapshot AS CHAR) FROM fulfillment_document_items WHERE id=?",String.class,itemId);String incoming=jsonText(v);boolean changed=!Objects.equals(previous,incoming);if(qty.compareTo(shipped)<0){rowResult="ERROR";status="ERROR";db.update("UPDATE fulfillment_documents SET local_status='NEEDS_REVIEW' WHERE id=?",documentId);createPlatformChangedException(documentId,sourceId,previous,incoming);}else{db.update("UPDATE fulfillment_document_items SET sku_id=COALESCE(?,sku_id),ordered_qty=?,imported_state=?,platform_updated_at=COALESCE(?,platform_updated_at),raw_snapshot=CAST(? AS JSON) WHERE id=?",skuId,qty,str(v,"source_status"),dateTime(v.get("updated_at")),incoming,itemId);if(changed){rowResult="UPDATED";updated++;if(shipped.signum()>0)createPlatformChangedException(documentId,sourceId,previous,incoming);}else{rowResult="DUPLICATE";duplicates++;}if(skuId==null)createUnmatchedException(shopId,str(v,"platform_sku"),itemId,sourceId);}}
            Long packageId=upsertPackage(documentId,v);if(packageId!=null)db.update("INSERT INTO fulfillment_package_items(package_id,document_item_id,packed_qty) VALUES (?,?,?) ON DUPLICATE KEY UPDATE packed_qty=VALUES(packed_qty)",packageId,itemId,qty);if("UNMATCHED".equals(status))rowResult="UNMATCHED";db.update("UPDATE fulfillment_import_rows SET row_status=?,document_id=?,item_id=? WHERE id=?",rowResult,documentId,itemId,source.get("id"));
        }
        String finalStatus=unmatched>0||number(batch,"errorRows")>0?"PARTIAL":"IMPORTED";db.update("UPDATE fulfillment_import_batches SET status=?,created_rows=?,updated_rows=?,duplicate_rows=?,unmatched_rows=?,committed_at=CURRENT_TIMESTAMP WHERE id=?",finalStatus,created,updated,duplicates,unmatched,id);
        audit(user,request,"fulfillment.import.commit","fulfillment_import_batch",String.valueOf(batch.get("batchNo")),Map.of("created",created,"updated",updated,"duplicates",duplicates,"unmatched",unmatched));
        return ApiResponse.ok(Map.of("batchNo",batch.get("batchNo"),"created",created,"updated",updated,"duplicates",duplicates,"unmatched",unmatched,"status",finalStatus));
    }

    @GetMapping("/documents")
    public ApiResponse<Map<String,Object>> documents(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String type,@RequestParam(required=false)String status,@RequestParam(required=false)String q,@AuthenticationPrincipal AuthUser user){view(user);int p=Math.max(1,page),s=Math.min(100,Math.max(1,pageSize));StringBuilder where=new StringBuilder(" WHERE 1=1");List<Object>a=new ArrayList<>();if(type!=null&&!type.isBlank()){where.append(" AND d.document_type=?");a.add(docType(type));}if(status!=null&&!status.isBlank()){where.append(" AND d.local_status=?");a.add(status);}if(q!=null&&!q.isBlank()){where.append(" AND (d.document_no LIKE ? OR d.source_document_id LIKE ? OR d.group_batch_id LIKE ? OR d.appointment_no LIKE ? OR d.shop_identifier LIKE ? OR EXISTS(SELECT 1 FROM fulfillment_document_items i WHERE i.document_id=d.id AND i.platform_sku LIKE ?))");for(int i=0;i<6;i++)a.add("%"+q.trim()+"%");}String from=" FROM fulfillment_documents d LEFT JOIN warehouses w ON w.id=d.warehouse_id";Long total=db.queryForObject("SELECT COUNT(*)"+from+where,Long.class,a.toArray());a.add(s);a.add((p-1)*s);var items=db.queryForList("SELECT d.id,d.document_no documentNo,d.document_type documentType,d.platform,d.shop_identifier shopIdentifier,d.source_document_id sourceDocumentId,d.source_status sourceStatus,d.group_batch_id groupBatchId,d.target_platform_warehouse targetPlatformWarehouse,d.local_status localStatus,d.appointment_no appointmentNo,d.pickup_start pickupStart,d.pickup_end pickupEnd,w.warehouse_name warehouseName,d.updated_at updatedAt,(SELECT COALESCE(SUM(ordered_qty),0) FROM fulfillment_document_items i WHERE i.document_id=d.id) orderedQty,(SELECT COALESCE(SUM(shipped_qty),0) FROM fulfillment_dispatch_items di JOIN fulfillment_dispatches x ON x.id=di.dispatch_id WHERE x.document_id=d.id AND x.status='HANDED_OFF') shippedQty"+from+where+" ORDER BY COALESCE(d.pickup_start,d.updated_at),d.id DESC LIMIT ? OFFSET ?",a.toArray());return ApiResponse.ok(Map.of("items",items,"total",Objects.requireNonNullElse(total,0L),"page",p,"pageSize",s));}

    @GetMapping("/documents/{id}")
    public ApiResponse<Map<String,Object>> document(@PathVariable long id,@AuthenticationPrincipal AuthUser user){view(user);Map<String,Object>d=db.queryForMap("SELECT d.*,w.warehouse_name warehouseName FROM fulfillment_documents d JOIN warehouses w ON w.id=d.warehouse_id WHERE d.id=?",id);d.put("items",db.queryForList("SELECT i.id,i.source_line_id sourceLineId,i.platform_sku_id platformSkuId,i.platform_sku platformSku,i.sku_id skuId,s.internal_sku internalSku,s.product_name productName,i.order_mode orderMode,i.order_date orderDate,i.ordered_qty orderedQty,i.imported_state importedState,COALESCE((SELECT SUM(x.shipped_qty) FROM fulfillment_dispatch_items x JOIN fulfillment_dispatches z ON z.id=x.dispatch_id WHERE x.document_item_id=i.id AND z.status='HANDED_OFF'),0) shippedQty FROM fulfillment_document_items i LEFT JOIN skus s ON s.id=i.sku_id WHERE i.document_id=? ORDER BY i.id",id));d.put("packages",db.queryForList("SELECT id,group_batch_id groupBatchId,package_no packageNo,label_no labelNo,label_filename labelFilename,appointment_no appointmentNo,pickup_start pickupStart,pickup_end pickupEnd,platform_updated_at platformUpdatedAt FROM fulfillment_packages WHERE document_id=? ORDER BY id",id));d.put("dispatches",db.queryForList("SELECT id,dispatch_no dispatchNo,dispatch_sequence dispatchSequence,status,handoff_reference handoffReference,created_at createdAt,handed_off_at handedOffAt FROM fulfillment_dispatches WHERE document_id=? ORDER BY dispatch_sequence",id));return ApiResponse.ok(d);}

    @GetMapping("/dispatches/{id}")
    public ApiResponse<Map<String,Object>> dispatchDetail(@PathVariable long id,@AuthenticationPrincipal AuthUser user){view(user);Map<String,Object>d=dispatch(id,false);d.put("dispatchNo",db.queryForObject("SELECT dispatch_no FROM fulfillment_dispatches WHERE id=?",String.class,id));d.put("items",db.queryForList("SELECT di.id dispatchItemId,di.document_item_id itemId,i.platform_sku platformSku,i.sku_id skuId,s.internal_sku internalSku,s.product_name productName,di.planned_qty plannedQty,di.picked_qty pickedQty,di.shipped_qty shippedQty FROM fulfillment_dispatch_items di JOIN fulfillment_document_items i ON i.id=di.document_item_id LEFT JOIN skus s ON s.id=i.sku_id WHERE di.dispatch_id=? ORDER BY di.id",id));return ApiResponse.ok(d);}

    @PostMapping("/documents/{id}/dispatches") @Transactional
    public ApiResponse<Map<String,Object>> createDispatch(@PathVariable long id,@RequestBody Map<String,Object> body,@AuthenticationPrincipal AuthUser user,HttpServletRequest request){operate(user);Map<String,Object>d=lockDocument(id);if(Set.of("CANCELLED","SHIPPED","NEEDS_REVIEW","SKU_UNMATCHED").contains(str(d,"local_status")))throw new IllegalArgumentException("当前单据状态不能创建发货批次");String key=blankDefault(str(body,"idempotencyKey"),UUID.randomUUID().toString());Long existing=db.query("SELECT id FROM fulfillment_dispatches WHERE document_id=? AND idempotency_key=?",rs->rs.next()?rs.getLong(1):null,id,key);if(existing!=null)return ApiResponse.ok(Map.of("id",existing,"duplicate",true));List<Map<String,Object>>lines=maps(body.get("items"));if(lines.isEmpty())throw new IllegalArgumentException("请选择本次发货 SKU 和数量");int seq=Objects.requireNonNullElse(db.queryForObject("SELECT MAX(dispatch_sequence) FROM fulfillment_dispatches WHERE document_id=?",Integer.class,id),0)+1;String dispatchNo=nextNo("FDX");db.update("INSERT INTO fulfillment_dispatches(dispatch_no,document_id,dispatch_sequence,idempotency_key,warehouse_id,note,created_by) VALUES (?,?,?,?,1,?,?)",dispatchNo,id,seq,key,str(body,"note"),user.id());long dispatch=lastId();BigDecimal requested=BigDecimal.ZERO;
        for(Map<String,Object>line:lines){long item=longValue(line,"itemId");BigDecimal qty=positive(line,"quantity");Map<String,Object>src=db.queryForMap("SELECT i.ordered_qty orderedQty,i.sku_id skuId,i.platform_sku platformSku FROM fulfillment_document_items i WHERE i.id=? AND i.document_id=? FOR UPDATE",item,id);if(src.get("skuId")==null)throw new IllegalArgumentException("SKU 未匹配，不能创建拣货批次："+src.get("platformSku"));BigDecimal shipped=decimalOrZero(db.queryForObject("SELECT COALESCE(SUM(di.shipped_qty),0) FROM fulfillment_dispatch_items di JOIN fulfillment_dispatches x ON x.id=di.dispatch_id WHERE di.document_item_id=? AND x.status='HANDED_OFF'",BigDecimal.class,item));if(shipped.add(qty).compareTo(decimal(src.get("orderedQty")))>0)throw new IllegalArgumentException("累计发货量不能超过订单/备货数量");db.update("INSERT INTO fulfillment_dispatch_items(dispatch_id,document_item_id,planned_qty) VALUES (?,?,?)",dispatch,item,qty);requested=requested.add(qty);}
        db.update("UPDATE fulfillment_documents SET first_dispatch_warehouse_locked=TRUE,local_status='PICKING' WHERE id=?",id);audit(user,request,"fulfillment.dispatch.create","fulfillment_dispatch",dispatchNo,body);return ApiResponse.ok(Map.of("id",dispatch,"dispatchNo",dispatchNo,"sequence",seq,"plannedQty",requested));}

    @PostMapping("/dispatches/{id}/pick") @Transactional
    public ApiResponse<Map<String,Object>> pick(@PathVariable long id,@RequestBody Map<String,Object> body,@AuthenticationPrincipal AuthUser user,HttpServletRequest request){operate(user);Map<String,Object>d=dispatch(id,true);if(!"PICKING".equals(d.get("status")))throw new IllegalArgumentException("当前批次不能拣货");String barcode=str(body,"barcode");Long skuId=body.get("skuId")==null?null:longValue(body,"skuId");if(skuId==null&&barcode!=null)skuId=db.query("SELECT id FROM skus WHERE barcode=? OR internal_sku=?",rs->rs.next()?rs.getLong(1):null,barcode,barcode);if(skuId==null)throw new IllegalArgumentException("条码未匹配到内部 SKU");BigDecimal qty=positive(body,"quantity");Map<String,Object>line=db.queryForMap("SELECT di.id dispatchItemId,di.planned_qty plannedQty,di.picked_qty pickedQty,i.id itemId,i.sku_id skuId,i.platform_sku platformSku FROM fulfillment_dispatch_items di JOIN fulfillment_document_items i ON i.id=di.document_item_id WHERE di.dispatch_id=? AND i.sku_id=? FOR UPDATE",id,skuId);BigDecimal after=decimal(line.get("pickedQty")).add(qty);if(after.compareTo(decimal(line.get("plannedQty")))>0)throw new IllegalArgumentException("本批次扫码拣货数量超过计划数量");db.update("INSERT IGNORE INTO inventory_stocks(sku_id,warehouse_id) VALUES (?,1)",skuId);BigDecimal stock=decimalOrZero(db.queryForObject("SELECT available_qty FROM inventory_stocks WHERE sku_id=? AND warehouse_id=1 FOR UPDATE",BigDecimal.class,skuId));db.update("UPDATE fulfillment_dispatch_items SET picked_qty=? WHERE id=?",after,line.get("dispatchItemId"));db.update("UPDATE fulfillment_dispatches SET status=IF((SELECT COUNT(*) FROM fulfillment_dispatch_items WHERE dispatch_id=? AND picked_qty<planned_qty)=0,'PICKED','PICKING') WHERE id=?",id,id);audit(user,request,"fulfillment.dispatch.pick","fulfillment_dispatch",String.valueOf(id),body);return ApiResponse.ok(Map.of("pickedQty",after,"plannedQty",line.get("plannedQty"),"availableQty",stock,"shortageWarning",stock.compareTo(after)<0));}

