    public ApiResponse<Map<String,Object>> shortage(@PathVariable long id,@RequestBody Map<String,Object>body,@AuthenticationPrincipal AuthUser user,HttpServletRequest request){operate(user);Map<String,Object>d=dispatch(id,true);if(!"PICKING".equals(d.get("status")))throw new IllegalArgumentException("当前批次不能登记缺货");long itemId=longValue(body,"itemId");Map<String,Object>item=db.queryForMap("SELECT i.sku_id skuId,di.planned_qty plannedQty,di.picked_qty pickedQty FROM fulfillment_dispatch_items di JOIN fulfillment_document_items i ON i.id=di.document_item_id WHERE di.dispatch_id=? AND i.id=?",id,itemId);BigDecimal qty=decimal(item.get("plannedQty")).subtract(decimal(item.get("pickedQty")));if(qty.signum()<=0)throw new IllegalArgumentException("该明细没有待拣缺货数量");String reason=str(body,"reason");if(reason==null||reason.isBlank())throw new IllegalArgumentException("请填写缺货原因");db.update("INSERT INTO fulfillment_shortages(document_item_id,shortage_qty,reason,created_by) VALUES (?,?,?,?)",itemId,qty,reason,user.id());db.update("UPDATE fulfillment_documents SET local_status='SHORTAGE' WHERE id=?",d.get("documentId"));long shortageId=lastId();audit(user,request,"fulfillment.shortage.create","fulfillment_shortage",String.valueOf(shortageId),body);return ApiResponse.ok(Map.of("id",shortageId,"shortageQty",qty,"skuId",item.get("skuId")));}

